public class DatasetUtilities_iterateRangeBounds_TriageGen1Test {

    @Test
    public void testIterateRangeBounds_StandardXYDataset_NormalValues() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(2);
        when(dataset.getYValue(0, 0)).thenReturn(10.0);
        when(dataset.getYValue(0, 1)).thenReturn(20.0);

        Range range = DatasetUtilities.iterateRangeBounds(dataset, false);

        assertEquals(10.0, range.getLower(), 1.0e-10);
        assertEquals(20.0, range.getUpper(), 1.0e-10);
    }

    @Test
    public void testIterateRangeBounds_StandardXYDataset_WithNaN() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(2);
        when(dataset.getYValue(0, 0)).thenReturn(Double.NaN);
        when(dataset.getYValue(0, 1)).thenReturn(5.0);

        Range range = DatasetUtilities.iterateRangeBounds(dataset, false);

        assertEquals(5.0, range.getLower(), 1.0e-10);
        assertEquals(5.0, range.getUpper(), 1.0e-10);
    }

    @Test
    public void testIterateRangeBounds_StandardXYDataset_EmptyReturnsNull() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(0);

        Range range = DatasetUtilities.iterateRangeBounds(dataset, false);

        assertNull(range);
    }

    @Test
    public void testIterateRangeBounds_IntervalXYDataset_IncludeIntervalTrue() {
        IntervalXYDataset ixyd = Mockito.mock(IntervalXYDataset.class);
        when(ixyd.getSeriesCount()).thenReturn(1);
        when(ixyd.getItemCount(0)).thenReturn(1);
        // Y value is 15, Start is 5, End is 25
        when(ixyd.getYValue(0, 0)).thenReturn(15.0);
        when(ixyd.getStartYValue(0, 0)).thenReturn(5.0);
        when(ixyd.getEndYValue(0, 0)).thenReturn(25.0);

        Range range = DatasetUtilities.iterateRangeBounds(ixyd, true);

        assertEquals(5.0, range.getLower(), 1.0e-10);
        assertEquals(25.0, range.getUpper(), 1.0e-10);
    }

    @Test
    public void testIterateRangeBounds_IntervalXYDataset_WithNaNValues() {
        IntervalXYDataset ixyd = Mockito.mock(IntervalXYDataset.class);
        when(ixyd.getSeriesCount()).thenReturn(1);
        when(ixyd.getItemCount(0)).thenReturn(1);
        when(ixyd.getYValue(0, 0)).thenReturn(Double.NaN);
        when(ixyd.getStartYValue(0, 0)).thenReturn(10.0);
        when(ixyd.getEndYValue(0, 0)).thenReturn(Double.NaN);

        Range range = DatasetUtilities.iterateRangeBounds(ixyd, true);

        assertEquals(10.0, range.getLower(), 1.0e-10);
        assertEquals(10.0, range.getUpper(), 1.0e-10);
    }

    @Test
    public void testIterateRangeBounds_OHLCDataset_IncludeIntervalTrue() {
        OHLCDataset ohlc = Mockito.mock(OHLCDataset.class);
        when(ohlc.getSeriesCount()).thenReturn(1);
        when(ohlc.getItemCount(0)).thenReturn(1);
        when(ohlc.getLowValue(0, 0)).thenReturn(100.0);
        when(ohlc.getHighValue(0, 0)).thenReturn(200.0);

        Range range = DatasetUtilities.iterateRangeBounds(ohlc, true);

        assertEquals(100.0, range.getLower(), 1.0e-10);
        assertEquals(200.0, range.getUpper(), 1.0e-10);
    }

    @Test
    public void testIterateRangeBounds_OHLCDataset_WithNaN() {
        OHLCDataset ohlc = Mockito.mock(OHLCDataset.class);
        when(ohlc.getSeriesCount()).thenReturn(1);
        when(ohlc.getItemCount(0)).thenReturn(1);
        when(ohlc.getLowValue(0, 0)).thenReturn(Double.NaN);
        when(ohlc.getHighValue(0, 0)).thenReturn(300.0);

        Range range = DatasetUtilities.iterateRangeBounds(ohlc, true);

        assertEquals(300.0, range.getLower(), 1.0e-10);
        assertEquals(300.0, range.getUpper(), 1.0e-10);
    }

    @Test
    public void testIterateRangeBounds_IntervalXYDataset_IncludeIntervalFalse() {
        // If includeInterval is false, it should fall into the 'else' block (standard XYDataset logic)
        // even if the object is an IntervalXYDataset.
        IntervalXYDataset ixyd = Mockito.mock(IntervalXYDataset.class);
        when(ixyd.getSeriesCount()).thenReturn(1);
        when(ixyd.getItemCount(0)).thenReturn(1);
        // In standard XY logic, only getYValue is used
        when(ixyd.getYValue(0, 0)).thenReturn(50.0);
        // These should be ignored because includeInterval is false
        when(ixyd.getStartYValue(0, 0)).thenReturn(10.0);
        when(ixyd.getEndYValue(0, 0)).thenReturn(100.0);

        Range range = DatasetUtilities.iterateRangeBounds(ixyd, false);

        assertEquals(50.0, range.getLower(), 1.0e-10);
        assertEquals(50.0, range.getUpper(), 1.0e-10);
    }
}
